const GREETINGS = {
  pe: { flag: "🇵🇪", country: "Perú",      message: "¡Hola desde Lima! Bienvenido a TSOFT Perú." },
  cl: { flag: "🇨🇱", country: "Chile",     message: "¡Hola po! Bienvenido a TSOFT Chile." },
  co: { flag: "🇨🇴", country: "Colombia",  message: "¡Quiubo! Bienvenido a TSOFT Colombia." },
  mx: { flag: "🇲🇽", country: "México",    message: "¡Qué onda! Bienvenido a TSOFT México." },
  ar: { flag: "🇦🇷", country: "Argentina", message: "¡Buenas! Bienvenido a TSOFT Argentina." },
  es: { flag: "🇪🇸", country: "España",    message: "¡Hola! Bienvenido a TSOFT España." }
};

function updateGreeting(countryCode) {
  var data      = GREETINGS[countryCode];
  var flagEl    = document.getElementById("greeting-flag");
  var countryEl = document.getElementById("greeting-country");
  var messageEl = document.getElementById("greeting-message");

  if (!data || !flagEl || !countryEl || !messageEl) {
    if (flagEl)    { flagEl.textContent    = ""; }
    if (countryEl) { countryEl.textContent = ""; }
    if (messageEl) { messageEl.textContent = ""; }
    return;
  }

  flagEl.textContent    = data.flag;
  countryEl.textContent = data.country;
  messageEl.textContent = data.message;
}

function init() {
  var selectEl = document.getElementById("country-select");

  if (!selectEl) {
    return;
  }

  selectEl.addEventListener("change", function (event) {
    updateGreeting(event.target.value);
  });

  updateGreeting(selectEl.value);
}

document.addEventListener("DOMContentLoaded", init);

/* ============================================================
   css/styles.css — Hola TSOFT
   ============================================================ */

/* ── PASO 1: Variables de paleta ─────────────────────────── */
:root {
  --color-azul-oscuro: #003087;
  --color-azul-medio:  #0057B8;
  --color-naranja:     #FF6B00;
  --color-blanco:      #FFFFFF;
  --color-fondo:       #F4F6FA;
}

/* ── PASO 2: Reset mínimo y box-sizing ───────────────────── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, Arial, sans-serif;
  background-color: var(--color-fondo);
  color: var(--color-azul-oscuro);
  min-height: 100vh;
}

/* ── PASO 3: Layout principal .page-wrapper ──────────────── */
.page-wrapper {
  display: grid;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
}

/* ── PASO 4: Header .site-header ─────────────────────────── */
.site-header {
  background-color: var(--color-azul-oscuro);
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.site-header__logo {
  color: var(--color-blanco);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
}

/* ── PASO 5: Área principal .main-content ────────────────── */
.main-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
  padding: 3rem 1rem;
}

/* ── PASO 6: Tarjeta de saludo .greeting-card ────────────── */
.greeting-card {
  background-color: var(--color-blanco);
  border-radius: 12px;
  box-shadow: 0 4px 24px rgba(0, 48, 135, 0.12);
  padding: 2.5rem 3rem;
  text-align: center;
  max-width: 480px;
  width: 100%;
}

.greeting-card__flag {
  font-size: 4rem;
  line-height: 1;
  margin-bottom: 0.5rem;
}

.greeting-card__text {
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-azul-oscuro);
  margin-bottom: 0.25rem;
}

.greeting-card__country {
  font-size: 1rem;
  color: var(--color-azul-medio);
  font-weight: 400;
}

/* ── PASO 7: Selector de país .country-selector ──────────── */
.country-selector {
  position: relative;
  display: inline-block;
}

.country-selector__select {
  appearance: none;
  -webkit-appearance: none;
  background-color: var(--color-blanco);
  border: 2px solid var(--color-azul-medio);
  border-radius: 8px;
  padding: 0.6rem 2.5rem 0.6rem 1rem;
  font-size: 1rem;
  color: var(--color-azul-oscuro);
  cursor: pointer;
  outline: none;
}

.country-selector__select:focus {
  border-color: var(--color-naranja);
}

.country-selector::after {
  content: "▾";
  position: absolute;
  right: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-azul-medio);
  pointer-events: none;
  font-size: 1rem;
}
